import { expect, test } from '@playwright/test'
import { seedBreakGlassSession } from './helpers/auth-seed'

/**
 * NS-ADR-124: Settings → Access. Personal API tokens are created with a name
 * and expiry, shown once, usable as a bearer against the real API, revocable,
 * and unable to manage tokens themselves. Runs against the real e2e backend
 * (break-glass sign-in); the token values are generated by the backend.
 */
const API = 'http://127.0.0.1:8000'

test('create a token, see it once, use it as a bearer, then revoke it', async ({
  page,
  request,
}) => {
  await seedBreakGlassSession(page)
  await page.goto('/settings?tab=access', { waitUntil: 'domcontentloaded' })
  await expect(page.getByTestId('access-tokens-panel')).toBeVisible()
  await expect(page.getByTestId('access-token-empty')).toBeVisible()

  await page.getByTestId('access-token-name').fill('e2e cli')
  await page.getByTestId('access-token-expiry').selectOption('30')
  await page.getByTestId('access-token-create').click()

  // One-time reveal.
  const reveal = page.getByTestId('access-token-reveal')
  await expect(reveal).toBeVisible()
  const token = (await page.getByTestId('access-token-value').innerText()).trim()
  expect(token).toMatch(/^nct_[A-Za-z0-9_-]{20,}$/)

  // The new token authenticates a direct API call as the owner.
  const me = await request.get(`${API}/api/auth/me`, {
    headers: { Authorization: `Bearer ${token}` },
  })
  expect(me.status()).toBe(200)
  expect((await me.json()).sub).toBe('local-admin')

  // A personal token cannot mint another token.
  const mint = await request.post(`${API}/api/auth/tokens`, {
    headers: { Authorization: `Bearer ${token}` },
    data: { name: 'nested', expires_in_days: 30 },
  })
  expect(mint.status()).toBe(403)

  // Dismissing the reveal removes the plaintext; a reload never shows it again.
  await page.getByTestId('access-token-dismiss').click()
  await expect(reveal).toHaveCount(0)
  await page.reload({ waitUntil: 'domcontentloaded' })
  await expect(page.getByTestId('access-tokens-panel')).toBeVisible()
  const row = page.locator('[data-testid^="access-token-row-"]').filter({ hasText: 'e2e cli' })
  await expect(row).toHaveCount(1)
  await expect(row).toContainText(token.slice(0, 8))
  expect(await page.content()).not.toContain(token)

  // Revoke: the row shows Revoked and the bearer stops working.
  await row.locator('[data-testid^="access-token-revoke-"]').click()
  await expect(row).toContainText('Revoked')
  const after = await request.get(`${API}/api/auth/me`, {
    headers: { Authorization: `Bearer ${token}` },
  })
  expect(after.status()).toBe(401)
})

test('sign out everywhere ends the session and returns to sign-in', async ({ page, request }) => {
  const access = await seedBreakGlassSession(page)
  await page.goto('/settings?tab=access', { waitUntil: 'domcontentloaded' })
  await expect(page.getByTestId('access-tokens-panel')).toBeVisible()
  await page.getByTestId('access-sign-out-everywhere').click()
  await page.waitForURL('**/login')
  const stale = await request.get(`${API}/api/auth/me`, {
    headers: { Authorization: `Bearer ${access}` },
  })
  expect(stale.status()).toBe(401)
})
